blinc_core = { git = "https://github.com/project-blinc/Blinc", rev = "2ca5f509e73600e7629f70d827b4f2850f5f9eb9", optional = true }
base64 = { version = "0.22", optional = true }

[features]
default = []
startup = []
scroll = []
virtual-scroll = []
switches = []
memory = ["dep:blinc_core", "dep:base64"]
hover = []

